import{_ as t,o as a,c as s,an as i}from"./chunks/framework.DrqfKv6l.js";const h=JSON.parse('{"title":"Cache géométrique compact","description":"","frontmatter":{},"headers":[],"relativePath":"cache-geometrique.md","filePath":"cache-geometrique.md"}'),n={name:"cache-geometrique.md"};function r(o,e,l,c,d,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<link rel="stylesheet" href="https://use.typekit.net/fnz7ojs.css"><h1 id="cache-geometrique-compact" tabindex="-1">Cache géométrique compact <a class="header-anchor" href="#cache-geometrique-compact" aria-label="Permalink to “Cache géométrique compact”">​</a></h1><p>Le calcul fractal conserve treize couches brutes : état de continuation, métriques d’orbite et payload interne de dérivées. La couleur ne lit pas cette représentation comme image. Elle consomme un <strong>display set</strong> plus petit et cohérent, produit directement par le resolve.</p><h2 id="abi-d-affichage" tabindex="-1">ABI d’affichage <a class="header-anchor" href="#abi-d-affichage" aria-label="Permalink to “ABI d’affichage”">​</a></h2><table tabindex="0"><thead><tr><th>Attachement</th><th>Format</th><th>Contenu</th><th style="text-align:right;">Octets par texel</th></tr></thead><tbody><tr><td>0</td><td><code>r32float</code></td><td>itération / état terminal</td><td style="text-align:right;">4</td></tr><tr><td>1</td><td><code>r32float</code></td><td><code>z.x</code></td><td style="text-align:right;">4</td></tr><tr><td>2</td><td><code>r32float</code></td><td><code>z.y</code></td><td style="text-align:right;">4</td></tr><tr><td>3</td><td><code>rgba16float</code></td><td>gradient x, gradient y, courbure, hauteur</td><td style="text-align:right;">8</td></tr><tr><td>4</td><td><code>r32uint</code></td><td>provenance, phase stripe, cohérence</td><td style="text-align:right;">4</td></tr></tbody></table><p>Le total est de <strong>24 octets par texel</strong> et cinq sorties MRT, contre huit sorties flottantes et 32 octets auparavant. Les trois premières sorties sont des vues d’une même texture tableau. Le live et le frozen possèdent chacun le même ensemble typé afin qu’une sélection ne mélange jamais valeur, géométrie et provenance de versions différentes.</p><p><code>z.xy</code> est volontairement conservé : il sert encore à l’itération lissée, aux orbit traps et aux mappings cartésiens fondés sur le point d’échappement.</p><h2 id="reaffectation-brute-au-point-terminal" tabindex="-1">Réaffectation brute au point terminal <a class="header-anchor" href="#reaffectation-brute-au-point-terminal" aria-label="Permalink to “Réaffectation brute au point terminal”">​</a></h2><p>Les treize couches brutes gardent leur sens historique tant que le texel est en continuation. Une fois l’orbite échappée, les emplacements devenus morts sont réaffectés sans ajouter de couche :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 itération       1 gradient.x      2 z.x           3 z.y</span></span>
<span class="line"><span>4 hauteur         5 gradient.y      6 stripe/cohérence compactées</span></span>
<span class="line"><span>7 Laplacien       8..12 payload z′/z″ de l’AA analytique</span></span></code></pre></div><p>La couche 6 terminale réserve 14 bits à la phase stripe et 14 bits à la cohérence, transportés par bitcast dans un flottant normal fini. Le resolve les décodera puis ajoutera les 4 bits de provenance propres au display set. Pour un texel en continuation, les couches 1, 4, 5, 6 et 7 conservent respectivement le marqueur de calcul, <code>derM.x</code>, <code>derM.y</code>, l’indice de référence et l’état de direction/exposant ; il n’y a donc aucune augmentation de l’ABI brut.</p><h2 id="geometrie" tabindex="-1">Géométrie <a class="header-anchor" href="#geometrie" aria-label="Permalink to “Géométrie”">​</a></h2><p>La quatrième sortie contient :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(dH/dx, dH/dy, Laplacien(H), H)</span></span></code></pre></div><p>où <code>H = -log(Dscreen)</code> et les dérivées sont exprimées par texel neutre de la source. Les shaders calculent toujours en f32 ; <code>rgba16float</code> n’est que le format de stockage.</p><p>À l’échappement, le noyau d’itération utilise, sur une branche d’échappement fixée :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A = z″/z′ - (1 + 1/log|z|) z′/z</span></span></code></pre></div><p>puis transforme <code>A</code> dans les axes du texel source. <code>z″</code> reste dans les couches brutes et n’est jamais transmis à la couleur. Les pas exacts et tous les sauts sélectionnables propagent <code>z″</code> par la règle de chaîne du second ordre. Un saut qui ne sait pas le faire est refusé au profit de l’itération exacte : il n’existe aucun repli par différences spatiales.</p><p>Le troisième canal est le Laplacien analytique de <code>H</code> :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ΔH = |z′/z|² / log²|z|</span></span></code></pre></div><p>Il est multiplié par le carré de la taille complexe d’un texel source. Les termes qui exigeraient <code>z‴</code> s’annulent parce que <code>log|z′|</code> et <code>log|z|</code> sont harmoniques sur une branche régulière. Gradient et hauteur sont saturés dans <code>[-64, 64]</code>, le Laplacien dans <code>[0, 64]</code>, avant leur conversion en demi-précision. Une production non finie est neutralisée à zéro dès l’échappement, sans lecture de voisin.</p><p>Une transition du nombre entier d’itérations d’échappement n’est pas une erreur de la formule : c’est une discontinuité entre branches. Les tests numériques mesurent donc la formule sur branche fixe et classent ces transitions à part.</p><h2 id="metadonnees" tabindex="-1">Métadonnées <a class="header-anchor" href="#metadonnees" aria-label="Permalink to “Métadonnées”">​</a></h2><p>Le mot de 32 bits est partagé ainsi :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bits  0..3   exposant e du support dyadique, pas = 2^e</span></span>
<span class="line"><span>bits  4..17  phase stripe, 14 bits non signés</span></span>
<span class="line"><span>bits 18..31  cohérence directionnelle, 14 bits non signés</span></span></code></pre></div><p>L’exposant zéro signifie un pixel exact de pas 1. Les valeurs positives décrivent seulement le support provisoire du resolve. <code>iter &lt; 0</code> signale l’absence de donnée, donc aucun bit de validité supplémentaire n’est requis. La phase stripe est interpolée sur le cercle ; la cohérence est interpolée linéairement. Leur erreur de quantification est bornée par <code>1/16383</code>.</p><p>L’indice entier de référence et l’ancien angle de dérivée ne font plus partie de l’ABI d’affichage. L’état de reprise de référence demeure dans la texture brute.</p><h2 id="changement-d-echelle-et-cache" tabindex="-1">Changement d’échelle et cache <a class="header-anchor" href="#changement-d-echelle-et-cache" aria-label="Permalink to “Changement d’échelle et cache”">​</a></h2><p>Pour un ratio spatial source vers affichage <code>r</code> :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Haffichage        = Hsource + log(r)</span></span>
<span class="line"><span>gradientAffichage = rotation(gradientSource) * r</span></span>
<span class="line"><span>courbureAffichage = courbureSource * r²</span></span></code></pre></div><p>Le merge live/frozen applique ces conversions avant d’écrire sa destination, puis choisit ensemble les cinq champs de la source dont le support effectif est le plus fin.</p><p>Une mutation du champ brut invalide la version résolue. Le resolve est omis uniquement lorsque la version typée correspond exactement à la version du champ. Un changement limité à la palette, à la lumière ou au matériau réutilise donc la géométrie ; une progression d’itération, une réinitialisation, un snapshot ou un merge produit une nouvelle version cohérente.</p><p>La couleur utilise directement le gradient pour les normales, les reflets, l’anisotropie et les ombres locales, ainsi que la courbure pour l’AO. Seuls les reliefs optionnels de stripe et de cohérence lisent encore des métadonnées voisines. La cible AA lit la hauteur dans <code>geometry.w</code> et l’AA analytique garde un accès séparé au payload brut uniquement pour son développement de Taylor.</p>`,33)])])}const g=t(n,[["render",r]]);export{h as __pageData,g as default};
